#!/usr/bin/env bash

# Flash ESP32-S3 MicroPython firmware + optional filesystem image.
#
# If a ./flash_args.txt is present (generated by CI), it will be used and should
# contain lines like:
#   0x0 base_firmware.bin
#   0x2D0000 vfs.bin
#
# Otherwise, this script falls back to flashing a lvgl_micropython merged image
# at 0x0 and (if present) vfs.bin at the default offset.

echo "Flashing ESP32-S3 firmware..."
echo "Make sure your ESP32-S3 is connected and in download mode"
echo ""

set -euo pipefail

RUN_DIR="$(pwd)"

append_unique() {
    local value="$1"
    local existing
    for existing in "${MATCHED_FILES[@]:-}"; do
        [ "$existing" = "$value" ] && return 0
    done
    MATCHED_FILES+=("$value")
}

find_first_existing_file() {
    local filename="$1"
    if [ -f "${RUN_DIR}/${filename}" ]; then
        echo "${RUN_DIR}/${filename}"
        return 0
    fi
    return 1
}

find_matching_files() {
    local pattern="$1"
    local f
    MATCHED_FILES=()
    for f in "${RUN_DIR}"/$pattern; do
        [ -f "$f" ] && append_unique "$f"
    done
}

PYTHON_BIN=$(command -v python3 || command -v python || true)
if [ -z "$PYTHON_BIN" ]; then
    echo "Error: Python not found. Please install Python 3."
    exit 1
fi

ESPTOOL_CMD="$PYTHON_BIN -m esptool"
if ! ${ESPTOOL_CMD} version >/dev/null 2>&1; then
    if ! command -v esptool >/dev/null 2>&1; then
        echo "Error: esptool not found. Please install with: pip install esptool"
        exit 1
    fi
    ESPTOOL_CMD="esptool"
fi

# Check if esptool is available
if ! $ESPTOOL_CMD version >/dev/null 2>&1; then
    echo "Error: esptool not found. Please install with: pip install esptool"
    exit 1
fi

FLASH_ARGS=()

FLASH_ARGS_FILE="$(find_first_existing_file "flash_args.txt" || true)"
if [ -n "${FLASH_ARGS_FILE}" ]; then
    echo "Using flash args file: ${FLASH_ARGS_FILE}"
    while read -r off file; do
        # skip blanks/comments
        [ -z "$off" ] && continue
        [[ "$off" =~ ^# ]] && continue
        if [ ! -f "$file" ]; then
            base_dir="$(dirname "${FLASH_ARGS_FILE}")"
            if [ -f "${base_dir}/${file}" ]; then
                file="${base_dir}/${file}"
            else
                echo "Error: '${file}' referenced in ${FLASH_ARGS_FILE} but not found"
                exit 1
            fi
        fi
        if [ ! -f "$file" ]; then
            echo "Error: '${file}' referenced in ${FLASH_ARGS_FILE} but not found"
            exit 1
        fi
        FLASH_ARGS+=("$off" "$file")
    done < "${FLASH_ARGS_FILE}"
else
    # Find a base firmware image to flash at 0x0
    BASE_FW="$(find_first_existing_file "base_firmware.bin" || true)"
    if [ -n "${BASE_FW}" ]; then
        FIRMWARE_BIN="${BASE_FW}"
        echo "Found firmware: $FIRMWARE_BIN"
    else
        find_matching_files "lvgl_micropy_ESP32_GENERIC_S3-*.bin"
        BINARY_FILES=("${MATCHED_FILES[@]}")
        if [ ${#BINARY_FILES[@]} -eq 0 ]; then
            echo "Error: No firmware binary found (base_firmware.bin or lvgl_micropy_ESP32_GENERIC_S3-*.bin)"
            exit 1
        elif [ ${#BINARY_FILES[@]} -eq 1 ]; then
            FIRMWARE_BIN="${BINARY_FILES[0]}"
            echo "Found firmware: $FIRMWARE_BIN"
        else
            echo "Multiple firmware binaries found. Please select one:"
            for i in "${!BINARY_FILES[@]}"; do
                echo "$((i+1)). ${BINARY_FILES[$i]}"
            done
            echo ""
            read -r -p "Enter your choice (1-${#BINARY_FILES[@]}): " choice
            
            if ! [[ "$choice" =~ ^[0-9]+$ ]] || [ "$choice" -lt 1 ] || [ "$choice" -gt ${#BINARY_FILES[@]} ]; then
                echo "Invalid selection"
                exit 1
            fi
            
            FIRMWARE_BIN="${BINARY_FILES[$((choice-1))]}"
            echo "Selected: $FIRMWARE_BIN"
        fi
    fi

    FLASH_ARGS+=("0x0" "$FIRMWARE_BIN")
fi

# Auto-detect port (you can override by setting PORT environment variable)
if [ -z "${PORT:-}" ]; then
    echo "Auto-detecting port..."
    # Try common ESP32 ports
    for port in /dev/ttyUSB0 /dev/ttyACM0 /dev/cu.usbserial-* /dev/cu.usbmodem* /dev/cu.SLAB_USBtoUART; do
        if compgen -G "$port" >/dev/null 2>&1 || [ -e "$port" ]; then
            PORT="$port"
            break
        fi
    done
    
    if [ -z "$PORT" ]; then
        echo "Could not auto-detect port. Please set PORT environment variable."
        echo "Example: PORT=/dev/ttyUSB0 $0"
        exit 1
    fi
fi

echo "Using port: $PORT"
echo ""

DO_ERASE="${ERASE_FIRST:-1}"
if [[ "$DO_ERASE" == "1" ]]; then
    # Erase flash first (recommended for clean install)
    echo "Erasing flash..."
    $ESPTOOL_CMD --chip esp32s3 --port "$PORT" erase-flash

    echo ""
else
    echo "Skipping erase (ERASE_FIRST=$DO_ERASE)"
fi

echo "Flashing firmware images..."

$ESPTOOL_CMD --chip esp32s3 \
    --port "$PORT" \
    --baud 460800 \
    write-flash --compress \
    "${FLASH_ARGS[@]}"
echo ""
echo "Flash completed successfully."
echo ""
echo "Your ESP32-S3 is now ready. You can:"
echo "1. Reset the device"
echo "2. Connect via serial terminal (115200 baud)"
echo "3. Upload your Python files to the device"
